type R={id:string;name:string;status:string;available:boolean;city:string;phone?:string;address?:string;description?:string;cuisines?:string[];image_url?:string;delivery_available?:boolean;pickup_available?:boolean;payment_methods?:string[];delivery_fee?:number;tax_rate?:number;min_order?:number;estimated_minutes?:number};
type O={id:string;ref:string;status:string;total:number;customer_name:string;items:any[];fulfillment:'delivery'|'pickup'};
type Menu={id:string;name:string;description:string;category:string;price:number;available:boolean;image_url?:string;variants:any[];add_ons:any[]};
export default function RestaurantDashboard(){
 const router=useRouter();const [restaurants,setRestaurants]=useState<R[]>([]);const [selected,setSelected]=useState<R|null>(null);const [orders,setOrders]=useState<O[]>([]);const [menu,setMenu]=useState<Menu[]>([]);
 const [name,setName]=useState('');const [paymentMethods,setPaymentMethods]=useState<string[]>(['cod','pickup']);const [razorpayAvailable,setRazorpayAvailable]=useState(false);const [phone,setPhone]=useState('');const [address,setAddress]=useState('');const [city,setCity]=useState('');const [description,setDescription]=useState('');const [cuisines,setCuisines]=useState('');const [imageURL,setImageURL]=useState('');const imageInput=useRef<any>(null);const [itemName,setItemName]=useState('');const [itemPrice,setItemPrice]=useState('');const [priceDrafts,setPriceDrafts]=useState<Record<string,string>>({});const [message,setMessage]=useState('');const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);
 const load=useCallback(async()=>{setLoading(true);try{const config=await api.get<any>('/restaurant/payments/config').catch(()=>({razorpay_enabled:false}));setRazorpayAvailable(Boolean(config.razorpay_enabled));const rows=await api.get<R[]>('/restaurants/mine');setRestaurants(rows);const current=selected?rows.find(r=>r.id===selected.id)||null:rows[0]||null;setSelected(current);if(current){setName(current.name||'');setPhone(current.phone||'');setAddress(current.address||'');setCity(current.city||'');setDescription(current.description||'');setCuisines((current.cuisines||[]).join(', '));setImageURL(current.image_url||'');setPaymentMethods(current.payment_methods||['cod','pickup']);const [o,m]=await Promise.all([api.get<O[]>(`/restaurants/${current.id}/orders`),api.get<Menu[]>(`/restaurants/${current.id}/menu`)]);setOrders(o);setMenu(m)}}catch(e:any){setMessage(e?.message||'Please sign in to use the restaurant dashboard.')}finally{setLoading(false)}},[selected?.id]);
 useFocusEffect(useCallback(()=>{load()},[load]));
 function togglePaymentMethod(method:string){setPaymentMethods(current=>current.includes(method)?current.filter(x=>x!==method):[...current,method])}
 async function create(){setBusy(true);setMessage('');try{if(paymentMethods.length===0){setMessage('Choose at least one payment method.');return;}const r=await api.post<R>('/restaurants',{name,phone,address,city,cuisines:cuisines.split(',').map(x=>x.trim()).filter(Boolean),description,image_url:imageURL||undefined,delivery_available:true,pickup_available:true,payment_methods:paymentMethods,delivery_fee:0,tax_rate:5,min_order:0,estimated_minutes:35});setRestaurants(prev=>[r,...prev]);setSelected(r);setMessage('Restaurant profile submitted. It remains unavailable until an admin approves it.')}catch(e:any){setMessage(e?.message||'Could not submit restaurant profile.')}finally{setBusy(false)}}
 async function updateProfile(){if(!selected)return;setBusy(true);setMessage('');try{if(paymentMethods.length===0){setMessage('Choose at least one payment method.');return;}const updated=await api.patch<R>(`/restaurants/${selected.id}`,{name,phone,address,city,cuisines:cuisines.split(',').map(x=>x.trim()).filter(Boolean),description,image_url:imageURL||undefined,delivery_available:selected.delivery_available??true,pickup_available:selected.pickup_available??true,payment_methods:paymentMethods,delivery_fee:selected.delivery_fee??0,tax_rate:selected.tax_rate??5,min_order:selected.min_order??0,estimated_minutes:selected.estimated_minutes??35});setSelected(updated);setRestaurants(prev=>prev.map(r=>r.id===updated.id?updated:r));setMessage('Profile saved and sent for approval review; public availability is paused until re-approved.')}catch(e:any){setMessage(e?.message||'Could not update restaurant profile.')}finally{setBusy(false)}}
 async function uploadLogo(e:any){const file:File|undefined=e?.target?.files?.[0];if(!file)return;setBusy(true);try{const uploaded=await api.upload(file,file.name);setImageURL(uploaded.url);setMessage('Restaurant image uploaded. Save the profile to persist it.')}catch(e:any){setMessage(e?.message||'Image upload failed.')}finally{setBusy(false);if(imageInput.current)imageInput.current.value=''}}
 async function addItem(){if(!selected)return;setBusy(true);setMessage('');try{await api.post(`/restaurants/${selected.id}/menu`,{name:itemName,price:Number(itemPrice),description:'',category:'Main',available:true,variants:[],add_ons:[]});setItemName('');setItemPrice('');setMessage('Menu item saved.');await load()}catch(e:any){setMessage(e?.message||'Could not save menu item.')}finally{setBusy(false)}}
 async function toggleItem(item:Menu){if(!selected)return;try{const updated=await api.patch<Menu>(`/restaurants/${selected.id}/menu/${item.id}`,{name:item.name,price:item.price,description:item.description||'',category:item.category||'Main',available:!item.available,image_url:item.image_url,variants:item.variants||[],add_ons:item.add_ons||[]});setMenu(prev=>prev.map(x=>x.id===item.id?updated:x))}catch(e:any){setMessage(e?.message||'Menu availability update failed.')}}
 async function deleteItem(item:Menu){if(!selected)return;try{await api.del(`/restaurants/${selected.id}/menu/${item.id}`);setMenu(prev=>prev.filter(x=>x.id!==item.id))}catch(e:any){setMessage(e?.message||'Menu item deletion failed.')}}
 async function updatePrice(item:Menu){if(!selected)return;const price=Number(priceDrafts[item.id]);if(!Number.isFinite(price)||price<0){setMessage('Enter a valid non-negative price.');return;}try{const updated=await api.patch<Menu>(`/restaurants/${selected.id}/menu/${item.id}`,{name:item.name,price,description:item.description||'',category:item.category||'Main',available:item.available,image_url:item.image_url,variants:item.variants||[],add_ons:item.add_ons||[]});setMenu(prev=>prev.map(x=>x.id===item.id?updated:x));setPriceDrafts(prev=>({...prev,[item.id]:String(price)}));setMessage('Menu price updated.')}catch(e:any){setMessage(e?.message||'Price update failed.')}}
 async function setStatus(order:O,status:string){try{await api.patch(`/restaurant/orders/${order.id}/status`,{status,note:''});setOrders(prev=>prev.map(x=>x.id===order.id?{...x,status}:x))}catch(e:any){setMessage(e?.message||'Status update failed.')}}
 return <RestaurantPage title="Restaurant dashboard" subtitle="Manage your restaurant, menu and incoming orders">
  <Text style={rs.muted}>Requires sign-in. New restaurant profiles need admin approval before they appear to customers.</Text>{loading?<ActivityIndicator color={t.primary}/>:null}
  {restaurants.length>0?<View style={rs.card}><Text style={rs.heading}>Your restaurants</Text>{restaurants.map(r=><Pressable key={r.id} style={[rs.chip,selected?.id===r.id&&rs.chipActive]} onPress={()=>{setSelected(r);setName(r.name||'');setPhone(r.phone||'');setAddress(r.address||'');setCity(r.city||'');setDescription(r.description||'');setCuisines((r.cuisines||[]).join(', '));setImageURL(r.image_url||'');setPaymentMethods(r.payment_methods||['cod','pickup']);setMessage('')}}><Text style={[rs.chipText,selected?.id===r.id&&rs.chipTextActive]}>{r.name} · {r.status}</Text></Pressable>)}{selected?<><Text style={rs.muted}>Availability: {selected.available?'Online':'Offline'}</Text><Pressable disabled={selected.status!=='approved'||busy} style={rs.button} onPress={async()=>{try{const updated=await api.patch<R>(`/restaurants/${selected.id}/availability`,{available:!selected.available});setSelected(updated);setRestaurants(prev=>prev.map(r=>r.id===updated.id?updated:r))}catch(e:any){setMessage(e?.message||'Availability update failed.')}}}><Text style={rs.buttonText}>{selected.available?'Go offline':'Go online'}</Text></Pressable></>:null}</View>:null}
  {selected?<View style={rs.card}><Text style={rs.heading}>Edit restaurant profile</Text>{[[name,setName,'Restaurant name'],[phone,setPhone,'Contact phone'],[address,setAddress,'Street address'],[city,setCity,'City'],[description,setDescription,'Description'],[cuisines,setCuisines,'Cuisine categories (comma separated)']].map(([value,setter,label]:any)=><TextInput key={label} value={value} onChangeText={setter} placeholder={label} placeholderTextColor={t.textMuted} style={rs.input}/>)}<Text style={rs.muted}>Accepted payment methods (saved with this restaurant)</Text><View style={rs.row}>{[{id:'cod',label:'Cash on Delivery'},{id:'pickup',label:'Cash at Pickup'}].map(m=><Pressable key={m.id} onPress={()=>togglePaymentMethod(m.id)} style={[rs.chip,paymentMethods.includes(m.id)&&rs.chipActive]}><Text style={rs.chipText}>{paymentMethods.includes(m.id)?'✓ ':''}{m.label}</Text></Pressable>)}</View><Text style={rs.muted}>{razorpayAvailable?'Razorpay credentials are configured, but the customer-facing Restaurant payment screen is not integrated yet. Do not enable online-only checkout.':'Online payment (Razorpay) is unavailable until the server is configured and its customer-facing checkout is integrated.'}</Text>{Platform.OS==='web'?<><input ref={imageInput} type="file" accept="image/*" style={{display:'none'}} onChange={uploadLogo}/><Pressable style={rs.chip} onPress={()=>imageInput.current?.click()}><Text style={rs.chipText}>{imageURL?'Change restaurant image':'Upload restaurant image'}</Text></Pressable></>:null}<Text style={rs.muted}>Saving material profile changes returns the restaurant to pending review.</Text><Pressable disabled={busy} style={rs.button} onPress={updateProfile}><Text style={rs.buttonText}>Save profile changes</Text></Pressable></View>:null}
  {!selected&&<View style={rs.card}><Text style={rs.heading}>Register a restaurant</Text>{Platform.OS==='web'&&!selected?<><input ref={imageInput} type="file" accept="image/*" style={{display:'none'}} onChange={uploadLogo}/><Pressable style={rs.chip} onPress={()=>imageInput.current?.click()}><Text style={rs.chipText}>{imageURL?'Change restaurant image':'Upload restaurant image'}</Text></Pressable></>:null}{[[name,setName,'Restaurant name'],[phone,setPhone,'Contact phone'],[address,setAddress,'Street address'],[city,setCity,'City'],[description,setDescription,'Description'],[cuisines,setCuisines,'Cuisine categories (comma separated)']].map(([value,setter,label]:any)=><TextInput key={label} value={value} onChangeText={setter} placeholder={label} placeholderTextColor={t.textMuted} style={rs.input}/>)}<Text style={rs.muted}>Choose accepted payment methods</Text><View style={rs.row}>{[{id:'cod',label:'Cash on Delivery'},{id:'pickup',label:'Cash at Pickup'}].map(m=><Pressable key={m.id} onPress={()=>togglePaymentMethod(m.id)} style={[rs.chip,paymentMethods.includes(m.id)&&rs.chipActive]}><Text style={rs.chipText}>{paymentMethods.includes(m.id)?'✓ ':''}{m.label}</Text></Pressable>)}</View><Text style={rs.muted}>{razorpayAvailable?'Razorpay credentials are configured, but the customer-facing Restaurant payment screen is not integrated yet. Do not enable online-only checkout.':'Online payment (Razorpay) is unavailable until the server is configured and its customer-facing checkout is integrated.'}</Text><Pressable disabled={busy||!name.trim()||!phone.trim()||!address.trim()||!city.trim()} style={rs.button} onPress={create}><Text style={rs.buttonText}>{busy?'Saving…':'Submit restaurant profile'}</Text></Pressable></View>}
